SELECT CASE WHEN YEAR(last_restock) < 2024 THEN 'before_2024' WHEN YEAR(last_restock) = 2024 THEN '2024' ELSE 'after_2024' END AS last_restock_cohort, store_id, MIN(last_restock) AS min_last_restock, SUM(quantity) AS total_quantity, ROUND(AVG(quantity), 2) AS avg_quantity FROM inventory GROUP BY CASE WHEN YEAR(last_restock) < 2024 THEN 'before_2024' WHEN YEAR(last_restock) = 2024 THEN '2024' ELSE 'after_2024' END, store_id;
